import { test, expect, Page } from '@playwright/test';

test.describe('API Error Banner Display', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display error banner when API call fails with 500 status', async () => {
    // Intercept the API call and return a 500 error
    await page.route('**/api/data', route => {
      route.abort('failed');
    });

    // Trigger the API call by clicking a button
    const fetchButton = page.getByRole('button', { name: /fetch data/i });
    await fetchButton.click();

    // Wait for error banner to appear
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Verify error message content
    await expect(errorBanner).toContainText(/failed to load/i);
  });

  test('should display error banner with specific error message on network failure', async () => {
    // Intercept and abort the network request
    await page.route('**/api/users', route => {
      route.abort('failed');
    });

    // Click button to trigger API call
    const loadUsersButton = page.getByRole('button', { name: /load users/i });
    await loadUsersButton.click();

    // Verify error banner is visible
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Check for specific error text
    const errorText = page.getByText(/unable to fetch users/i);
    await expect(errorText).toBeVisible();

    // Verify banner has error styling
    await expect(errorBanner).toHaveClass(/error/);
  });

  test('should display error banner with retry button when API times out', async () => {
    // Intercept API and simulate timeout
    await page.route('**/api/products', route => {
      route.abort('timedout');
    });

    // Trigger the API call
    const getProductsButton = page.getByRole('button', { name: /get products/i });
    await getProductsButton.click();

    // Wait for error banner
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Verify timeout error message
    await expect(errorBanner).toContainText(/request timed out/i);

    // Verify retry button exists in banner
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });

  test('should display error banner with close button and allow dismissal', async () => {
    // Intercept API to return error
    await page.route('**/api/settings', route => {
      route.abort('failed');
    });

    // Trigger API call
    const loadSettingsButton = page.getByRole('button', { name: /load settings/i });
    await loadSettingsButton.click();

    // Verify error banner appears
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Find and click close button
    const closeButton = page.getByRole('button', { name: /close|dismiss/i }).first();
    await closeButton.click();

    // Verify banner is dismissed
    await expect(errorBanner).not.toBeVisible();
  });

  test('should display error banner with error details when API returns 4xx error', async () => {
    // Intercept API and return 400 error with details
    await page.route('**/api/validate', route => {
      route.abort('failed');
    });

    // Trigger validation API call
    const validateButton = page.getByRole('button', { name: /validate/i });
    await validateButton.click();

    // Check error banner visibility
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/validation failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error banner has appropriate styling
    await expect(errorBanner).toHaveAttribute('role', 'alert');
  });

  test('should persist error banner until user action or timeout', async () => {
    // Intercept API to fail
    await page.route('**/api/sync', route => {
      route.abort('failed');
    });

    // Trigger API call
    const syncButton = page.getByRole('button', { name: /sync/i });
    await syncButton.click();

    // Verify error banner appears
    const errorBanner = page.getByRole('alert');
    await expect(errorBanner).toBeVisible();

    // Wait a moment and verify banner is still visible
    await page.waitForTimeout(2000);
    await expect(errorBanner).toBeVisible();

    // Verify banner persists until dismissed
    const dismissButton = page.getByRole('button', { name: /dismiss|close/i }).first();
    await dismissButton.click();
    await expect(errorBanner).not.toBeVisible();
  });
});
